max_limit = 10

def find_next_numbers(sequence, max_limit):
    numbers = sequence

    # If the limit is already reached or we don't have enough numbers to find a pattern
    if len(numbers) >= 10 + 4:
        return "".join([str(num) for num in numbers])

    # Check different possible patterns
    patterns = [
        lambda a, b, c: a - b + c,
        lambda a, b, c: b - a + c,
        lambda a, b, c: a + b - c
    ]

    # Try to find the pattern by comparing consecutive elements
    for i in range(len(numbers) - 2):
        for pattern in patterns:
            try:
                next_number = pattern(numbers[i], numbers[i+1], numbers[i+2])
                if next_number >= 100 and next_number < 1000:
                    numbers.append(next_number)
                    return "".join([str(num) for num in numbers])
            except IndexError:
                pass

    # If no pattern was found, return existing numbers (since no new numbers were added)
    return "".join([str(num) for num in numbers])

